#!/usr/bin/env bash
# Print the three most frequent client IPs, retaining log order for ties.
set -euo pipefail

script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)

awk '
    NF {
        ip = $1
        if (!(ip in count)) {
            seen_at[ip] = ++unique_count
            ips[unique_count] = ip
        }
        count[ip]++
    }
    END {
        for (place = 1; place <= 3 && place <= unique_count; place++) {
            best = ""
            for (i = 1; i <= unique_count; i++) {
                ip = ips[i]
                if (chosen[ip])
                    continue
                if (best == "" || count[ip] > count[best] || \
                    (count[ip] == count[best] && seen_at[ip] < seen_at[best]))
                    best = ip
            }
            print best
            chosen[best] = 1
        }
    }
' "$script_dir/access.log"
